INSERT INTO `tb_carteira` (`ID_carteira`, `nome_aluno`, `valor_total`, `tipo`, `descricao`, `idaluno`, `data_gerada`, `usuario`) VALUES
(1, 'IAMILY DA ROCHA MUNIZ ', 60.00, 'ENTRADA', 'VALOR PAGO NO MÊS DE ABRIL: R$ 500,00. COMO O VALOR FOI PAGO VIA PIX E ANTES DA DATA DE VENCIMENTO, FICARAM R$ 60,00 DE SALDO PARA A PRÓXIMA MENSALIDADE.', 134, '2023-04-03', 'LETICIA'),
(2, 'LUAN BENJAMIN COELHO RAMOS ', 10.00, 'ENTRADA', 'PAGAMENTO MENSALIDADE ESPORTE. VALOR DA MENSALIDADE: R$ 80,00. VALOR RECEBIDO VIA PIX: 90,00. ADICIONADO R$ 10,OO À CARTEIRA PARA SER DEBITADO NA PRÓXIMA MENSALIDADE. ', 74, '2023-04-06', 'LETICIA'),
(3, 'ISABELA DA SILVA SOUZA', 10.00, 'ENTRADA', 'O VALOR PAGO NA MENSALIDADE DE ABRIL FOI O DE R$450,00. COMO FOI PAGO DENTRO DO PRAZO, POSSUI DESCONTO E SAI NO VALOR DE R$ 440,00. SENDO ASSIM, ADICIONADO À CARTEIRA PARA SER DEBITADO NA PRÓXIMA MENSALIDADE O VALOR DE R$ 10,00.', 24, '2023-04-10', 'LETICIA'),
(8, 'ALUNO TESTE', 100.00, 'ENTRADA', '', 119, '2023-04-19', 'ADMIN'),
(9, 'ALUNO TESTE', 100.00, 'SAIDA', 'Mensalidade', 119, '2023-04-19', 'ADMIN'),
(12, 'LUAN BENJAMIN COELHO RAMOS ', 10.00, 'SAIDA', 'VENDA', 74, '2023-05-05', 'LETICIA'),
(13, 'THEO DOS ANJOS RIBEIRO ', 5.00, 'ENTRADA', 'A MÃE DO ALUNO THÉO REALIZOU UM PIX PARA O ALUNO IR PARA O CINEMA DA RAINHA NO DIA 05/05. ENTRETANTO, PRÓXIMO À HORA DE VIR PARA A AULA, O ALUNO APRESENTOU MAL ESTAR E CONSEQUENTEMENTE, NÃO VEIO PARA A ESCOLA. SENDO ASSIM, O VALOR PAGO NÃO FOI UTILIZADO, FICANDO DE SALDO PARA A PRÓXIMA VENDA DO REI OU RAINHA CAIPIRA.', 31, '2023-05-05', 'LETICIA'),
(14, 'BIANCA SOARES SILVA DE MIRANDA ', 5.00, 'ENTRADA', 'A MÃE DA ALUNA BIANCA MIRANDA EFETUOU PAGAMENTO PARA O CINEMA. ENTRETANTO, O PAI DA ALUNA EFETUOU O PAGAMENTO ANTERIORMENTE. SENDO ASSIM,  O PAGAMENTO REALIZADO PELA MÃE, PERMANECE DE SALDO PARA A PRÓXIMA VENDA DO REI OU RAINHA CAIPIRA DE 2023.', 13, '2023-05-05', 'LETICIA'),
(17, 'ANTHONY DE SOUZA EGAS FIGUEIREDO ', 15.00, 'ENTRADA', 'PAGAMENTO REALIZADO PARA A BRINCADEIRA \"ACERTE A CESTA\". FEITO PELA MÃE E PELO PAI DO ALUNO. O ALUNO PARTICIPOU APENAS 1X, O VALOR AQUI ADICIONADO, PODERÁ SER DEBITADO PARA SUA PARTICIPAÇÃO NAS PRÓXIMAS BRINCADEIRAS PROMOVIDAS PELO REI/RAINHA CAIPIRA DE 2023.', 59, '2023-05-08', 'LETICIA'),
(18, 'LUIZ GUILHERME DE OLIVEIRA AMORIM MACEDO', 5.00, 'ENTRADA', 'O ALUNO PAGOU PELA BRINCADEIRA DO REI, NO DIA 08/05, PORÉM NO MESMO DIA TEVE CONSULTA E ACABOU FALTANDO A AULA, DEIXANDO R$5,00 DE SALDO PARA SER DEBITADO NA PRÓXIMA BRINCADEIRA.', 7, '2023-05-08', 'LETICIA'),
(19, 'ISABELA DA SILVA SOUZA', 10.00, 'SAIDA', 'Mensalidade', 24, '2023-05-08', 'LETICIA'),
(20, 'BETINA AKEMI RODRIGUES MINORI', 40.00, 'ENTRADA', 'VALOR RECEBIDO INICIALMENTE: R$ 50,00 NO DIA 04/05, PAGO PELA MÃE DA ALUNA. NO DIA 05/05 FOI DEBITADO R$5,00 PARA QUE A ALUNA PARTICIPASSE DO CINEMA E DO DIA 08/05 FOI DEBITADO MAIS R$5,00 PARA SUA PARTICIPAÇÃO NA BRINCADEIRA PROMOVIDA POR UM DOS CANDIDATOS A REI CAIPIRA DA FESTA JULINA DO ATENIENSE EM 2023.', 26, '2023-05-08', 'LETICIA'),
(21, 'BIANCA SOARES SILVA DE MIRANDA ', 5.00, 'ENTRADA', 'VALOR PAGO PELO PAI NO DIA 08/05, PORÉM, HOUVE UMA EVENTUALIDADE E A ALUNA ACABOU AUSENTANDO-SE DA ESCOLA NESSE DIA, PERMANECENDO ESSE VALOR PODENDO SER DEBITADO EM OUTROS EVENTOS PROPORCIONADOS PELOS REIS E RAINHAS CAIPIRAS DE 2023', 13, '2023-05-08', 'LETICIA'),
(22, 'FABIO LOPES LADISLAU ', 1.00, 'ENTRADA', 'LANCHE DO DIA 08/05 FOI PAGO R$6,00. SENDO QUE, CONFORME INFORMADO PREVIAMENTE PARA OS PAIS, HOUVE ALTERAÇÃO NO VALOR. ADICIONANDO ASSIM, 1,00 DE SALDO À CARTEIRA DO ALUNO.', 97, '2023-05-09', 'LETICIA'),
(23, 'FABIO LOPES LADISLAU ', 1.00, 'SAIDA', 'VENDA', 97, '2023-05-09', 'LETICIA'),
(24, 'JOÃO PEDRO DE OLIVEIRA SANTOS', 5.00, 'ENTRADA', 'PAGO R$30,00 LANCHE SEMANAL. ENTRETANTO, O ALUNO COMPARECEU NA QUARTA-FEIRA, SENDO DEBITADO QUARTA, QUINTA, SEXTA, SEGUNDA, TERCA. PERMANECENDO 5,00 DE SALDO QUE PODE SER DEBITADO NA PROX COMPRA', 128, '2023-05-10', 'LETICIA'),
(25, 'ANTHONY DE SOUZA EGAS FIGUEIREDO ', 15.00, 'SAIDA', 'VENDA', 59, '2023-05-10', 'LETICIA'),
(26, 'THEO DOS ANJOS RIBEIRO ', 5.00, 'SAIDA', 'VENDA', 31, '2023-05-15', 'LETICIA'),
(27, 'BETINA AKEMI RODRIGUES MINORI', 40.00, 'SAIDA', 'VENDA', 26, '2023-05-15', 'LETICIA'),
(28, 'CHRISTINE BARREIROS BENOLIEL ', 5.00, 'ENTRADA', 'PAGO 30 PELO LANCHE SEMANAL, DEVIDO REAJUSTE NO VALOR DO LANCHE, FICA ADICIONADO À CARTEIRA O VALOR DE 5,00.\r\n', 9, '2023-05-15', 'LETICIA'),
(31, 'CHRISTINE BARREIROS BENOLIEL ', 5.00, 'ENTRADA', 'PAGO 30 PELO LANCHE SEMANAL, DEVIDO REAJUSTE NO VALOR DO LANCHE, FICA ADICIONADO À CARTEIRA O VALOR DE 5,00.', 9, '2023-05-22', 'LETICIA'),
(32, 'BIANCA SOARES SILVA DE MIRANDA ', 10.00, 'SAIDA', 'VENDA', 13, '2023-05-22', 'LETICIA'),
(33, 'AGNES HELENA MOREIRA CEZAR ', 7.00, 'ENTRADA', 'VALOR PAGO PELO PAI E PELA MÃE PARA O CINEMA. VÁLIDO APENAS 1 VEZ POR ALUNO. SENDO ASSIM, SOBRAM 7,00 QUE PODERÃO SER DEBITADOS NAS PRÓXIMAS VENDAS DOS REIS E RAINHAS DA FESTA JULINA', 93, '2023-06-02', 'LETICIA'),
(34, 'JOÃO PEDRO DE OLIVEIRA SANTOS', 5.00, 'SAIDA', 'Mensalidade', 128, '2023-06-05', 'LETICIA'),
(35, 'JOÃO PEDRO DE OLIVEIRA SANTOS', 5.00, 'ENTRADA', 'ENVIADO 30,00 REFERENTE AO LANCHE SEMANAL. VALOR TOTAL: 25,00. SOBRANDO 5,00 DE SALDO QUE PODE SER DEBITADO NA PRÓXIMA COMPRA.', 128, '2023-06-05', 'LETICIA'),
(36, 'MARIA VALENTINA DE SANTANNA COSTA NOGUEIRA', 30.00, 'ENTRADA', 'VALOR ADICIONADO À CARTEIRA POIS O VALOR PAGO NESTE DIA É REFERENTE À MENSALIDADE JUN + BALÉ, QUE TOTALIZA EM R$520,00. ENTRETANTO, O VALOR PAGO FOI DE R$550,00, ADICIONADO À CARTEIRA DA ALUNA O VALOR QUE SOBROU (30,00) QUE PODERÁ SER DEBITADO NA PRÓXIMA MENSALIDADE OU NO DECORRER DAS VENDAS DOS REIS E RAINHAS CAIPIRAS.', 110, '2023-06-05', 'LETICIA'),
(37, 'PEDRO PETTINARI BARBOSA FERREIRA', 12.00, 'ENTRADA', 'VALOR A SR DEBITADO NO DECORRER DAS PRÓXIMAS VENDAS DO REI E RAINHA CAIPIRA 2023 ', 5, '2023-06-19', 'LETICIA'),
(39, 'ESTHER LASMAR MARINHO ', 80.00, 'ENTRADA', 'VALOR PAGO DIA 05/07 (QUARTA-FEIRA) REFERENTE À MENSALIDADE DOS ESPORTES NO MÊS DE JULHO. ENTRETANTO, NÃO HAVERÁ ESPORTE NO MÊS DE JULHO, FICANDO COMO VALOR A SER DEBITADO REFERENTE ÀS MODALIDADES NO MÊS DE AGOSTO.', 10, '2023-07-05', 'LETICIA'),
(40, 'GABRIEL VIANA MENDONÇA', 40.00, 'ENTRADA', 'VALOR RECEBIDO PARA A 2A MESA DA FESTA JULINA. ENTRETANTO, A MÃE DO ALUNO (LETICIA) SOLICITOU QUE FICASSE DE SALDO PARA SER DEBITADO NA PRÓXIMA MENSALIDADE, SENDO ASSIM, PERMANECE 40,00 DE SALDO.', 37, '2023-07-05', 'LETICIA'),
(41, 'GABRIEL VIANA MENDONÇA', 40.00, 'SAIDA', 'VALOR RETIRADO PARA ABATER O VALOR PENDENTE DO COFRE DO PROJETO DE EDUCAÇÃO FINANCEIRA.', 37, '2023-10-06', 'LETICIA'),
(42, 'HENRICO PIETRO NATAL DA SILVA FARIAS', 200.00, 'ENTRADA', 'VALOR A SER DEBITADO NA MENSALIDADE DO MÊS DE DEZEMBRO/ 2023', 143, '2023-11-21', 'LETICIA'),
(43, 'MELINDA DE SOUSA MAGALHÃES', 0.00, 'SAIDA', 'Mensalidade', 19, '2023-12-06', 'LETICIA'),
(44, 'HENRICO PIETRO NATAL DA SILVA FARIAS', 200.00, 'SAIDA', 'Mensalidade', 143, '2023-12-14', 'LETICIA'),
(45, 'ARTHUR MOTA SOUZA DE JESUS', 200.00, 'ENTRADA', 'SALDO P DEBITAR DA PROX MENSALIDADE', 111, '2024-01-22', 'IURY'),
(46, 'GEOVANNA HOLANDA ARAÚJO', 10.00, 'ENTRADA', 'ADICIONADO À CARTEIRA R$10,00 REFERENTE À TROCA DO SHORT SAIA DE 6 ANOS PARA O SHORT SAIA DE 4 ANOS. VALOR A SER DEBITADO NA PRÓXIMA MENSALIDADE. ?', 16, '2024-01-25', 'LETICIA'),
(47, 'BERNARDO BENEVIDES MENDES', 20.00, 'ENTRADA', 'FICOU DE SALDO 20,00 A SER DEBITADO, POIS NO DIA 10/01/2024 NAO TINHA TROCO EM ESPECIE ', 175, '2024-02-01', 'LETICIA'),
(48, 'BERNARDO BENEVIDES MENDES', 20.00, 'SAIDA', 'VENDA', 175, '2024-02-01', 'LETICIA'),
(49, 'GUILHERME DE SOUZA SILVA ', 200.00, 'ENTRADA', 'VALOR PAGO A MAIS NA MENSALIDADE DO ALUNO GUILHERME SILVA, FICANDO A SER DEBITADO NA PRÓXIMA MENSALIDADE (REFERENTE AO MÊS DE MARÇO).', 41, '2024-02-05', 'LETICIA'),
(50, 'CAIO ARTHUR ABREU MILHOMEM ', 100.00, 'ENTRADA', 'FOI PAGO DIA 05/02 O VALOR DE 600,00 REAIS, DENTRO DO PRAZO PARA PAGAMENTOS COM DESCONTO, FICANDO ASSIM 100,00 DE SALDO', 118, '2024-02-06', 'LETICIA'),
